@Service
class OrderFacade(
    private val inventory: InventoryService,
    private val pricing: PricingService,
    private val repo: OrderRepository) {
    @Transactional                              // coarse-grained use-case boundary
    fun placeOrder(req: PlaceOrderRequest): OrderId {
        val quote = pricing.quote(req.sku, req.qty)
        inventory.reserve(req.sku, req.qty)
        return repo.insert(Order(req.customerId, quote))
    }
}
